def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row)
    background = max((v for v in counts if v != 0), key=lambda v: counts[v])
    marker_colors = [v for v in counts if v not in (0, background)]
    if not marker_colors:
        return [row[:] for row in grid]
    marker = marker_colors[0]
    threshold = sum(v == marker for row in grid for v in row)

    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                not seen[ny][nx] and grid[ny][nx] == 0):
                            seen[ny][nx] = True
                            q.append((ny, nx))
            if len(component) >= threshold:
                for y, x in component:
                    out[y][x] = marker
    return out
